import { Ionicons } from '@expo/vector-icons';
import { useRouter, type Href } from 'expo-router';
import { Pressable, StyleSheet, Text, View } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

import { DesignColors, DesignSpacing, DesignTypography, fontFamily } from '@/constants/design';
import { useUnreadMessages } from '@/hooks/use-unread-messages';

export type BottomTab = 'home' | 'discover' | 'messages' | 'profile';

const ROUTES: Record<BottomTab, Href> = {
  home: '/(tabs)',
  // Typed routes are regenerated by the dev server; the route file already exists.
  discover: '/(tabs)/discover' as Href,
  messages: '/(tabs)/messages',
  profile: '/(tabs)/profile',
};

export function AppBottomNav({ activeTab = 'home' }: { activeTab?: BottomTab }) {
  const insets = useSafeAreaInsets();
  const router = useRouter();
  const unreadCount = useUnreadMessages();

  const navigate = (tab: BottomTab) => {
    router.replace(ROUTES[tab]);
  };

  return (
    <View style={[styles.nav, { paddingBottom: Math.max(insets.bottom, DesignSpacing.sm) }]}>
      <NavItem
        icon="home-outline"
        activeIcon="home"
        label="Home"
        active={activeTab === 'home'}
        onPress={() => navigate('home')}
      />
      <NavItem
        icon="compass-outline"
        activeIcon="compass"
        label="Discover"
        active={activeTab === 'discover'}
        onPress={() => navigate('discover')}
      />
      <NavItem
        icon="chatbubble-outline"
        activeIcon="chatbubble"
        label="Messages"
        active={activeTab === 'messages'}
        onPress={() => navigate('messages')}
        showDot={unreadCount > 0}
      />
      <NavItem
        icon="person-outline"
        activeIcon="person"
        label="Profile"
        active={activeTab === 'profile'}
        onPress={() => navigate('profile')}
      />
    </View>
  );
}

function NavItem({
  icon,
  activeIcon,
  label,
  active = false,
  showDot = false,
  onPress,
}: {
  icon: keyof typeof Ionicons.glyphMap;
  activeIcon: keyof typeof Ionicons.glyphMap;
  label: string;
  active?: boolean;
  showDot?: boolean;
  onPress?: () => void;
}) {
  return (
    <Pressable
      accessibilityRole="tab"
      accessibilityLabel={label}
      accessibilityState={{ selected: active }}
      onPress={onPress}
      style={styles.item}
    >
      <View style={styles.iconWrap}>
        <Ionicons
          name={active ? activeIcon : icon}
          size={22}
          color={active ? DesignColors.primaryBright : DesignColors.onSurface}
        />
        {showDot ? <View style={styles.dot} testID={`nav-dot-${label}`} /> : null}
      </View>
      <Text style={[styles.label, active && styles.labelActive]}>{label}</Text>
    </Pressable>
  );
}

const styles = StyleSheet.create({
  nav: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-around',
    paddingHorizontal: DesignSpacing.sm,
    paddingTop: DesignSpacing.md,
    backgroundColor: DesignColors.scrimDeep,
    borderTopWidth: 1,
    borderTopColor: DesignColors.cardBorder,
  },
  item: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
    minHeight: 48,
    gap: 4,
    paddingVertical: 4,
  },
  iconWrap: {
    position: 'relative',
  },
  dot: {
    position: 'absolute',
    top: -2,
    right: -4,
    width: 8,
    height: 8,
    borderRadius: 4,
    backgroundColor: DesignColors.primary,
  },
  label: {
    ...DesignTypography.labelSm,
    color: DesignColors.onSurface,
    fontFamily,
  },
  labelActive: {
    color: DesignColors.primaryBright,
    fontWeight: '700',
  },
});
